<script setup lang="ts">
import AppIcon from '../../../../../shared/components/layout/AppIcon.vue'
import { projectStatusLabels, type Project, type ProjectStatus } from '../../types/project'

defineProps<{ projects: Project[]; loading: boolean }>()
const emit = defineEmits<{ edit: [project: Project] }>()
const statusClass: Record<ProjectStatus, string> = { draft: 'draft', active: 'active', on_hold: 'hold', completed: 'complete', cancelled: 'cancelled' }
function formatDate(value: string | null) {
  return value ? new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(`${value}T00:00:00`)) : '—'
}
</script>

<template>
  <div>
    <div v-if="loading" class="list-state">Memuat project...</div>
    <div v-else-if="!projects.length" class="list-state"><span class="empty-mark"><AppIcon name="folder-kanban" :size="22" /></span><strong>Belum ada project</strong><span>Project yang dibuat akan tampil di sini.</span></div>
    <div v-else class="table-wrap"><table><thead><tr><th>Kode project</th><th>Project</th><th>Pelanggan</th><th>Jenis</th><th>Target selesai</th><th>Status</th><th>Aplikasi</th><th><span class="sr-only">Aksi</span></th></tr></thead><tbody>
      <tr v-for="project in projects" :key="project.id"><td><span class="code">{{ project.code }}</span></td><td><strong>{{ project.name }}</strong></td><td><span class="related"><b>{{ project.customer.name }}</b><small>{{ project.customer.code }}</small></span></td><td><span class="related"><b>{{ project.project_type.name }}</b><small>{{ project.project_type.code }}</small></span></td><td>{{ formatDate(project.target_end_date) }}</td><td><span class="status" :class="statusClass[project.status]"><i></i>{{ projectStatusLabels[project.status] }}</span></td><td><a v-if="project.application_url" class="app-link" :href="project.application_url" target="_blank" rel="noopener noreferrer" :aria-label="`Buka aplikasi ${project.name} di tab baru`" title="Buka aplikasi"><AppIcon name="arrow-up-right" :size="15" /><span>Buka</span></a><span v-else class="no-link">—</span></td><td><div class="actions"><button type="button" :aria-label="`Edit ${project.name}`" title="Edit" @click="emit('edit', project)"><AppIcon name="edit" :size="16" /></button></div></td></tr>
    </tbody></table></div>
  </div>
    <div v-if="projects.length && !loading" class="project-cards"><article v-for="project in projects" :key="project.id" class="project-card"><div class="card-top"><div class="identity-copy"><strong>{{ project.name }}</strong><small>{{ project.code }}</small></div><span class="status" :class="statusClass[project.status]"><i></i>{{ projectStatusLabels[project.status] }}</span></div><div class="card-details"><span><small>Pelanggan</small><strong>{{ project.customer.name }}</strong><code>{{ project.customer.code }}</code></span><span><small>Jenis proyek</small><strong>{{ project.project_type.name }}</strong><code>{{ project.project_type.code }}</code></span><span><small>Target selesai</small><strong>{{ formatDate(project.target_end_date) }}</strong></span></div><div class="card-actions"><a v-if="project.application_url" class="app-link" :href="project.application_url" target="_blank" rel="noopener noreferrer"><AppIcon name="arrow-up-right" :size="15" /> Buka aplikasi</a><span v-else class="no-link">Tautan belum diatur</span><button type="button" @click="emit('edit', project)"><AppIcon name="edit" :size="15" /> Edit</button></div></article></div>
</template>

